import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); String line = br.readLine(); if (line == null) return; StringTokenizer st = new StringTokenizer(line); int a = Integer.parseInt(st.nextToken()); int b = Integer.parseInt(st.nextToken()); int diff = a - b; int lastDigit = diff % 10; if (lastDigit != 1) { diff = (diff / 10) * 10 + (lastDigit + 1); } else { diff = (diff / 10) * 10 + 2; } System.out.println(diff); } }